declare(strict_types=1);require __DIR__.'/common.php';require __DIR__.'/redis.php';if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')respond(405,['error'=>'只支持 POST']);$r=redis_or_null();if($r)rate_limit($r,'admin-login',8,300);$u=mb_substr(trim((string)($_POST['username']??'')),0,64);$p=mb_substr((string)($_POST['password']??''),0,128);$a=app_config('admin');if(!hash_equals((string)$a['username'],$u)||!hash_equals((string)$a['password'],$p))respond(401,['error'=>'管理员账号或密码不正确','code'=>'admin_invalid']);start_admin_session();session_regenerate_id(true);$_SESSION[(string)$a['session_key']]=true;respond(200,['ok'=>true]);
